// Format contract expiry data for notifications
const contracts = $input.all();

if (contracts.length === 0) {
  return {
    json: {
      hasContracts: false,
      message: "No contracts expiring soon",
      execution_id: $execution.id || `exec_${Date.now()}`
    }
  };
}

// Group by expiry status
const grouped = {};
contracts.forEach(contract => {
  const status = contract.json.expiry_status || 'expiring_30_days';
  if (!grouped[status]) {
    grouped[status] = [];
  }
  grouped[status].push(contract.json);
});

// Format Mattermost attachments
const attachments = [];
const colors = {
  'expired': '#FF6B6B',
  'unsigned_expired': '#FF6B6B',
  'expiring_7_days': '#FFD93D',
  'unsigned_expiring_7_days': '#FFD93D',
  'expiring_30_days': '#FFA500',
  'unsigned_expiring_30_days': '#FFA500'
};

const titles = {
  'expired': '⚠️ Expired Contracts',
  'unsigned_expired': '⚠️ Unsigned Expired Contracts',
  'expiring_7_days': '🔴 Contracts Expiring in 7 Days',
  'unsigned_expiring_7_days': '🔴 Unsigned Contracts Expiring in 7 Days',
  'expiring_30_days': '🟡 Contracts Expiring in 30 Days',
  'unsigned_expiring_30_days': '🟡 Unsigned Contracts Expiring in 30 Days'
};

Object.keys(grouped).forEach(status => {
  const contractsInGroup = grouped[status];
  const fields = contractsInGroup.slice(0, 10).map(contract => ({
    short: true,
    title: contract.contract_number || 'N/A',
    value: `${contract.work_name || 'N/A'}\nExpires: ${contract.expiry_date || 'N/A'}\nStatus: ${contract.status || 'N/A'}`
  }));

  attachments.push({
    color: colors[status] || '#4ECDC4',
    title: titles[status] || `Contracts - ${status}`,
    fields: fields,
    footer: `Total: ${contractsInGroup.length} contract(s)`,
    ts: Math.floor(Date.now() / 1000)
  });
});

// Determine channel
let channel = '#contracts-expiry';
if (grouped['expired'] || grouped['unsigned_expired'] || grouped['expiring_7_days'] || grouped['unsigned_expiring_7_days']) {
  channel = '#contracts-urgent';
}

// Count by status
const expiredCount = (grouped['expired'] || []).length + (grouped['unsigned_expired'] || []).length;
const expiring7DaysCount = (grouped['expiring_7_days'] || []).length + (grouped['unsigned_expiring_7_days'] || []).length;
const expiring30DaysCount = (grouped['expiring_30_days'] || []).length + (grouped['unsigned_expiring_30_days'] || []).length;

// Format email data
const emailHtml = `
<div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto; padding: 20px;">
  <h2 style="color: #333; border-bottom: 2px solid #FF6B6B; padding-bottom: 10px;">⚠️ Contract Expiry Reminder</h2>

  <p>You have <strong>${contracts.length}</strong> contract(s) expiring soon:</p>

  <ul style="list-style: none; padding: 0;">
    ${expiredCount > 0 ? `<li style="color: #FF6B6B; margin: 10px 0;"><strong>${expiredCount} expired contract(s)</strong></li>` : ''}
    ${expiring7DaysCount > 0 ? `<li style="color: #FFD93D; margin: 10px 0;"><strong>${expiring7DaysCount} contract(s) expiring in 7 days</strong></li>` : ''}
    ${expiring30DaysCount > 0 ? `<li style="color: #FFA500; margin: 10px 0;"><strong>${expiring30DaysCount} contract(s) expiring in 30 days</strong></li>` : ''}
  </ul>

  <table style="width: 100%; border-collapse: collapse; margin: 20px 0; background: #f9f9f9;">
    <thead>
      <tr style="background: #4ECDC4; color: white;">
        <th style="padding: 12px; text-align: left;">Contract Number</th>
        <th style="padding: 12px; text-align: left;">Work</th>
        <th style="padding: 12px; text-align: left;">Expiry Date</th>
        <th style="padding: 12px; text-align: left;">Status</th>
      </tr>
    </thead>
    <tbody>
      ${contracts.map(contract => {
        const urgencyColor = contract.json.expiry_status?.includes('expired') ? '#FF6B6B' : 
                            contract.json.expiry_status?.includes('7_days') ? '#FFD93D' : '#FFA500';
        return `
        <tr>
          <td style="padding: 12px; border-bottom: 1px solid #ddd;">${contract.json.contract_number || 'N/A'}</td>
          <td style="padding: 12px; border-bottom: 1px solid #ddd;">${contract.json.work_name || 'N/A'}</td>
          <td style="padding: 12px; border-bottom: 1px solid #ddd; color: ${urgencyColor};"><strong>${contract.json.expiry_date || 'N/A'}</strong></td>
          <td style="padding: 12px; border-bottom: 1px solid #ddd;">${contract.json.status || 'N/A'}</td>
        </tr>`;
      }).join('')}
    </tbody>
  </table>

  <p style="margin-top: 30px;">Please review and take necessary actions.</p>

  <p style="margin-top: 30px;">Best regards,<br><strong>OrientClassicsManager System</strong></p>
</div>
`;

// Get unique recipients (creators and translators)
const recipients = new Map();
contracts.forEach(contract => {
  if (contract.json.creator_email) {
    recipients.set(contract.json.creator_email, {
      email: contract.json.creator_email,
      name: contract.json.creator_name,
      role: 'creator',
      contracts: []
    });
  }
  if (contract.json.translator_email) {
    recipients.set(contract.json.translator_email, {
      email: contract.json.translator_email,
      name: contract.json.translator_name,
      role: 'translator',
      contracts: []
    });
  }
});

// Assign contracts to recipients
contracts.forEach(contract => {
  if (contract.json.creator_email && recipients.has(contract.json.creator_email)) {
    recipients.get(contract.json.creator_email).contracts.push(contract.json);
  }
  if (contract.json.translator_email && recipients.has(contract.json.translator_email)) {
    recipients.get(contract.json.translator_email).contracts.push(contract.json);
  }
});

return {
  json: {
    hasContracts: true,
    totalContracts: contracts.length,
    expiredCount: expiredCount,
    expiring7DaysCount: expiring7DaysCount,
    expiring30DaysCount: expiring30DaysCount,
    // Mattermost data
    mattermost_text: `⚠️ **Contract Expiry Reminder**\n\nYou have ${contracts.length} contract(s) expiring soon.`,
    mattermost_channel: channel,
    mattermost_attachments: attachments,
    // Email data
    email_html: emailHtml,
    email_subject: `⚠️ Contract Expiry Reminder: ${expiredCount > 0 ? expiredCount + ' Expired' : ''} ${expiring7DaysCount > 0 ? expiring7DaysCount + ' Expiring in 7 Days' : ''} ${contracts.length} Total`,
    recipients: Array.from(recipients.values()),
    // Execution tracking
    execution_id: $execution.id || `exec_${Date.now()}`,
    workflow_name: 'Contract Expiry Reminder'
  }
};

// Format email for each recipient
const recipient = $json;
const notificationData = $node['Format Contract Expiry Data'].json || {};

// Filter contracts for this recipient
const recipientContracts = recipient.contracts || [];

const emailHtml = `
<div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto; padding: 20px;">
  <h2 style="color: #333; border-bottom: 2px solid #FF6B6B; padding-bottom: 10px;">⚠️ Contract Expiry Reminder</h2>

  <p>Dear ${recipient.name},</p>

  <p>You have <strong>${recipientContracts.length}</strong> contract(s) expiring soon:</p>

  <table style="width: 100%; border-collapse: collapse; margin: 20px 0; background: #f9f9f9;">
    <thead>
      <tr style="background: #4ECDC4; color: white;">
        <th style="padding: 12px; text-align: left;">Contract Number</th>
        <th style="padding: 12px; text-align: left;">Work</th>
        <th style="padding: 12px; text-align: left;">Expiry Date</th>
        <th style="padding: 12px; text-align: left;">Status</th>
      </tr>
    </thead>
    <tbody>
      ${recipientContracts.map(contract => {
        const urgencyColor = contract.expiry_status?.includes('expired') ? '#FF6B6B' : 
                            contract.expiry_status?.includes('7_days') ? '#FFD93D' : '#FFA500';
        return `
        <tr>
          <td style="padding: 12px; border-bottom: 1px solid #ddd;">${contract.contract_number || 'N/A'}</td>
          <td style="padding: 12px; border-bottom: 1px solid #ddd;">${contract.work_name || 'N/A'}</td>
          <td style="padding: 12px; border-bottom: 1px solid #ddd; color: ${urgencyColor};"><strong>${contract.expiry_date || 'N/A'}</strong></td>
          <td style="padding: 12px; border-bottom: 1px solid #ddd;">${contract.status || 'N/A'}</td>
        </tr>`;
      }).join('')}
    </tbody>
  </table>

  <p style="margin-top: 30px;">Please review and take necessary actions.</p>

  <p style="margin-top: 30px;">Best regards,<br><strong>OrientClassicsManager System</strong></p>
</div>
`;

return {
  json: {
    to: recipient.email,
    subject: `⚠️ Contract Expiry Reminder: ${recipientContracts.length} contract(s) require attention`,
    html: emailHtml,
    recipient_name: recipient.name,
    contract_count: recipientContracts.length
  }
};
